/** Routes tagged `marketing · lead packs`. */
export class MarketingLeadPacksResource extends Resource {
  /**
   * Tira a tag de busca da lista da
   * organização.
   *
   * Idempotente. O nicho continua existindo para quem mais o usa, e os
   * pacotes já comprados não mudam.
   *
   * `DELETE /v1/marketing/niches/{slug}`
   *
   * @param slug Chave do nicho (`caminhao-de-mudanca`)
   * @param options Per-call overrides.
   */
  forgetNiche(slug: string, options?: RequestOptions): Promise<void> {
    return this._http.request({ method: 'DELETE', path: `/v1/marketing/niches/${seg(slug)}`, responseType: 'void', options });
  }

  /**
   * Um pacote, com o andamento.
   *
   * É o que a tela consulta enquanto o pacote espera a coleta.
   *
   * `GET /v1/marketing/lead-packs/{id}`
   *
   * @param id ID do pacote (Snowflake)
   * @param options Per-call overrides.
   */
  getLeadPack(id: string, options?: RequestOptions): Promise<S.MarketingLeadPack> {
    return this._http.request({ method: 'GET', path: `/v1/marketing/lead-packs/${seg(id)}`, options });
  }

  /**
   * A cobertura de cada par.
   *
   * `GET /v1/marketing/lead-packs/coverage`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  leadPackCoverage(query: MarketingLeadPacksLeadPackCoverageQuery, options?: RequestOptions): Promise<S.MarketingLeadPackCoverage> {
    return this._http.request({ method: 'GET', path: `/v1/marketing/lead-packs/coverage`, query, options });
  }

  /**
   * Os nichos com pacotes da
   * organização esperando coleta.
   *
   * Para cada nicho: quantos pacotes esperam, quantos a organização pôs na
   * frente e quantos estão coletando agora. Os escolhidos vêm primeiro.
   *
   * `GET /v1/marketing/lead-packs/queue`
   *
   * @param options Per-call overrides.
   */
  leadPackQueue(options?: RequestOptions): Promise<S.MarketingLeadPackQueue> {
    return this._http.request({ method: 'GET', path: `/v1/marketing/lead-packs/queue`, options });
  }

  /**
   * Os pacotes da organização (keyset).
   *
   * Cada pacote traz a coleta do par, com os contadores de andamento.
   *
   * `GET /v1/marketing/lead-packs`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listLeadPacks(query?: MarketingLeadPacksListLeadPacksQuery, options?: RequestOptions): Promise<S.MarketingLeadPacksPage> {
    return this._http.request({ method: 'GET', path: `/v1/marketing/lead-packs`, query, options });
  }

  /**
   * Iterates every item of `listLeadPacks`, following `next_page_token` page after page.
   *
   * `GET /v1/marketing/lead-packs`
   */
  listLeadPacksAll(query?: MarketingLeadPacksListLeadPacksQuery, options?: RequestOptions): Paginator<NonNullable<S.MarketingLeadPacksPage["items"]>[number], S.MarketingLeadPacksPage> {
    return new Paginator((page_token) => this.listLeadPacks({ ...query, page_token } as MarketingLeadPacksListLeadPacksQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * O catálogo de nichos (dado de referência) e
   * as tags de busca da organização.
   *
   * Não tem preço: o preço do pacote é do billing.
   *
   * `GET /v1/marketing/niches`
   *
   * @param options Per-call overrides.
   */
  listNiches(options?: RequestOptions): Promise<S.MarketingNiches> {
    return this._http.request({ method: 'GET', path: `/v1/marketing/niches`, options });
  }

  /**
   * Quantos pares a organização
   * ainda pode pedir sem pagar.
   *
   * Cada pacote pago que terminou sem leads deixa um crédito, e cada crédito
   * paga um par novo qualquer pelo resgate.
   *
   * `GET /v1/marketing/lead-packs/credits`
   *
   * @param options Per-call overrides.
   */
  packCredits(options?: RequestOptions): Promise<S.MarketingPackCredits> {
    return this._http.request({ method: 'GET', path: `/v1/marketing/lead-packs/credits`, options });
  }

  /**
   * Põe os pacotes do nicho que
   * esperam coleta na frente da fila, ou os devolve à ordem de chegada.
   *
   * Vale para os pacotes que esperam agora. A escolha reordena só a
   * organização entre os pacotes da mesma posição: a concessão escolhida nunca
   * passa na frente de um pacote pago. Idempotente.
   *
   * `PUT /v1/marketing/lead-packs/queue/{slug}`
   *
   * @param slug Chave do nicho (`dentistas`)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  prioritizeNiche(slug: string, body: S.MarketingPrioritizeNiche, options?: RequestOptions): Promise<S.MarketingLeadPackQueue> {
    return this._http.request({ method: 'PUT', path: `/v1/marketing/lead-packs/queue/${seg(slug)}`, body, options });
  }

  /**
   * Paga pares com o crédito que os
   * pacotes pagos e não entregues deixaram.
   *
   * Qualquer par, o mesmo que falhou ou outro. Tudo ou nada: sem crédito para
   * todos os pares, nenhum pacote nasce.
   *
   * `POST /v1/marketing/lead-packs/redeem`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  redeemPackCredits(body: S.MarketingRedeemPackCredits, options?: RequestOptions): Promise<S.MarketingRedeemedPacks> {
    return this._http.request({ method: 'POST', path: `/v1/marketing/lead-packs/redeem`, body, options });
  }

  /**
   * O nicho que o catálogo não mostra.
   *
   * Casa com o catálogo pelo nome ou termo de busca; senão cria o nicho,
   * fora da vitrine, buscado como foi escrito.
   *
   * `POST /v1/marketing/niches/resolve`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  resolveNiche(body: S.MarketingResolveNiche, options?: RequestOptions): Promise<S.MarketingResolvedNiche> {
    return this._http.request({ method: 'POST', path: `/v1/marketing/niches/resolve`, body, options });
  }
}

